steps=[]
def s(i,t,a,p,v,record=False,diagram=False):
    steps.append(dict(id=i,title=t,instruction=a,depends_on=[steps[-1]['id']] if steps else [],source_pdf_pages=p,verification=[v],record_required=record,diagram_reference_required=diagram,source_links=[URL+'#page='+str(x) for x in p] if diagram else [],origin='Original source-based summary; retained grip/body and observation gates are bounded workflow adaptations.'))
s('prepare','Confirm the throttle and working state','Start with the assembled stock bike, engine stopped and securely supported upright. Confirm the throttle and engine idle were operating normally before this access job. Keep the throttle body, TPS, hydraulic units and the bonded grip/tube assembly intact. Arrange the configured Yamaha diagnostic tool and tachometer for the final operating check.',[96,161,163,165],'Stock serviceable throttle and normal prior idle confirmed.',True)
s('record','Record the original cable positions','Record the pull and return cable positions at the grip against the page 4-39 diagram. Record existing grip free play, which must be 3–6 mm before this service. Preserve the outer cable routing and adjustment so neither cable is swapped on refit.',[96,161],'Pull/return identities, routing and initial free play recorded.',True,True)
s('housing-open','Open the cable housing','Pull back the rubber cover. Remove the housing screws and separate the throttle cable housing without pulling on the cables.',[161,163],'Housing open; rubber cover and screws retained.',diagram=True)
s('ends-release','Release the two grip-end cables','Disengage the pull and return cable ends from their original seats in the throttle tube as shown. Support the cables without kinking them and withdraw the complete grip/tube assembly from the bar. Do not peel the bonded rubber grip off its tube or disturb the cable ends at the throttle body.',[161,163,165],'Both identified ends released; intact grip/tube retained.',diagram=True)
s('inspect','Check the released parts','Inspect the tube sliding surface and cable-end seats for damage and check that the cables move without binding. Keep dirt out of the open housing. A damaged or frayed cable needs a separate full cable-renewal operation before this access job can return to service.',[163,165],'Retained parts accepted; no damaged cable or binding.',True)
s('lubricate','Lubricate the sliding and cable-end surfaces','Apply lithium-soap-based grease to the throttle-grip sliding surface. Lightly grease the cable ends and inside of the grip as shown. Keep grease away from the exterior gripping surface and the brake.',[165],'Sliding and cable-end contact surfaces lubricated.',diagram=True)
s('ends-fit','Reconnect pull and return cables','Restore each identified cable end to its original seat and groove in the throttle tube. Place the rubber cover and slide the intact grip/tube onto the handlebar. Confirm both cable ends and their outer housings are seated correctly before closing the housing.',[161,165],'Both cable ends seated in the correct positions without crossing.',diagram=True)
s('housing-close','Secure the housing','Fit the housing and tighten its screws to 3.8 Nm. Check grip movement immediately. If the housing causes binding, reposition and retighten it, then check again. Restore the housing cover and rubber cover.',[165],'Housing torqued; grip moves smoothly and returns.',diagram=True)
s('static-check','Verify free play and return before starting','With the engine stopped, check free play and smooth full return through the steering travel. The retained setup must still have 3–6 mm free play and no binding. If not, correct seating/routing before starting; do not use a running engine to diagnose a bound throttle.',[96,165,166],'Record 3–6 mm free play and full return at centre and both steering limits.',True)
s('warm','Start for the operating check','Only with all work on the bike complete, select neutral and use a ventilated location. Start according to engine temperature: the warm engine does not need the starter knob. For a cold start, use the starter knob when ambient temperature is 15 °C or below, keep the throttle untouched while operating it, and limit each starter attempt to 10 seconds with a pause between attempts. After a cold start, warm for one or two minutes at a steady 3000–5000 r/min and return the starter knob to its normal position.',[39,40],'Engine running normally, starter enrichment returned.')
s('idle-check','Check the warm idle','Use the correctly configured YDT 90890-03275 (US USB) or 90890-03273 to confirm coolant at 70–80 °C. Measure speed with tachometer 90890-06760 or YU-39951-B, connected as shown to the ignition-coil high-tension lead. With the starter knob fully returned and normal filter/compression/free play, verify 1900–2100 r/min. If necessary, adjust the idle screw; clockwise raises speed.',[96],'Record temperature and accepted idle speed.',True,True)
s('final-adjust','Set the final grip free play','Stop the engine. If final adjustment is needed after idle setting, loosen the grip adjuster locknut, turn the adjuster to obtain 3–6 mm free play, and tighten the locknut. Confirm smooth full return again.',[96],'Record final 3–6 mm free play and secure locknut.',True,True)
s('steering-check','Verify idle through steering travel','Restart the warm engine without starter enrichment. Turn the handlebar fully left and right: idle must not change. If it changes, stop and correct cable routing/seating or adjustment before repeating this check. Hold the engine-stop switch until the engine fully stops when the check is finished.',[39,40,96],'Record unchanged idle across steering travel; engine stopped.',True)
d=dict(schema_version=1,id='yamaha-2026-yz450f-throttle-grip-cable-access-v1',target=dict(manufacturer='Yamaha',model='YZ450F',model_year=2026,region='US',variant='standard'),component='engine',affected_components=['engine','throttle','controls'],scope_confirmed=True,status='SOURCE_REVIEWED_BOUNDED_PROCEDURE',publication_status='APPROVED',title='Disconnect and refit throttle cables at the grip',completeness='Complete grip-end cable disconnection/refit on a serviceable stock assembled bike, with retained bonded grip and throttle-body ends, lubrication, free-play/return and operating checks. Full cable renewal and throttle-body removal are separate.',source=dict(source_url=URL,document_sha256=SHA,document_revision='D03-2819U-10 / LIT-11626-39-20; First edition April 2025',pdf_pages=[39,40,96,161,163,165,166],printed_pages=['1-27','1-28','3-12','4-39','4-41','4-43','4-44'],review_status='APPROVED',review_note='New operation diagrams161/163/165 and adjustment96 visually reviewed; start/stop39/40 and166 closure text crosschecked against exact PDF and earlier approved engine closure. Independent year_groups_research review approved: rendered96/161/165 and text39/40/96/163–166.'),applicability=dict(included='Exact US2026 standard stock YZ450F, serviceable original throttle grip/tube and cables.',excluded=['Other models/years','Cable replacement or body-end disconnection','Grip rebonding or replacement','TPS or throttle-body adjustment','Handlebar, hydraulic or engine removal'],year_inheritance='NONE'),entry_state=['Assembled stock bike, engine stopped, normal idle/freeplay established before service.','Intact bonded grip, cables and routing serviceable; diagnostic/tachometer equipment configured for final check.'],exit_state=['Pull/return ends correctly restored; housing and covers closed.','Final free play and smooth return accepted; idle unchanged with steering travel; engine stopped.'],required_tools=[dict(name=x) for x in ['Appropriate housing driver and calibrated 3.8 Nm torque tool','Free-play measuring scale','Configured exact Yamaha diagnostic tool and its supplied operating instructions','Digital tachometer 90890-06760 or YU-39951-B','Stable bike support']],required_parts=[],prerequisites=['No known cable damage or pre-existing abnormal idle.','Keep cable outer routing and body-end adjustment unchanged.','If composed into another job, complete that job and restore all assemblies before the running-check range.'],consumables=['Lithium-soap-based grease'],critical_stop_conditions=['Damaged cable, uncertain pull/return identity or binding','Insufficient clearance without disturbing excluded components','Idle changes through steering travel or abnormal engine operation'],steps=steps,operation_dependencies=[],phase_boundaries=dict(access=['prepare','ends-release'],refit=['inspect','static-check'],operating_closure=['warm','steering-check']))
(P/'throttle-grip-cable-access-v1.procedure.json').write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
